Input: {"question": "When did Akarin debut?", "source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0392-7317f9c313a2:d00", "start": 0, "end": 144, "text": "Akari Suda Suda passed SKE48's 3rd generation auditions on 11 November 2009, and debuted on 8 December 2009 at SKE48's Team S stage performance."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0392-7317f9c313a2:d00", "start": 145, "end": 193, "text": "On 27 February 2010, she was promoted to Team S."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0392-7317f9c313a2:d00", "start": 194, "end": 241, "text": "Her first SKE48 Senbatsu was for the single \"1!"}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0392-7317f9c313a2:d00", "start": 242, "end": 244, "text": "2!"}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0392-7317f9c313a2:d00", "start": 245, "end": 247, "text": "3!"}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0392-7317f9c313a2:d00", "start": 248, "end": 250, "text": "4!"}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0392-7317f9c313a2:d00", "start": 251, "end": 263, "text": "Yoroshiku!\"."}, "D1S8": {"document_number": 1, "doc_id": "ramdocs-0392-7317f9c313a2:d00", "start": 264, "end": 335, "text": "In the 2011 general elections, Suda placed 36th and entered Undergirls."}, "D1S9": {"document_number": 1, "doc_id": "ramdocs-0392-7317f9c313a2:d00", "start": 336, "end": 383, "text": "In April 2013, she was transferred to Team KII."}, "D1S10": {"document_number": 1, "doc_id": "ramdocs-0392-7317f9c313a2:d00", "start": 384, "end": 441, "text": "She started activities as a Team KII member in July 2013."}, "D1S11": {"document_number": 1, "doc_id": "ramdocs-0392-7317f9c313a2:d00", "start": 442, "end": 509, "text": "In the 2013 general elections, Suda entered senbatsu at 16th place."}, "D1S12": {"document_number": 1, "doc_id": "ramdocs-0392-7317f9c313a2:d00", "start": 510, "end": 576, "text": "In February 2014, during the AKB48 Group Shuffle, it was announced"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0392-7317f9c313a2:d01", "start": 0, "end": 139, "text": "Akari Suda passed SKE48's 3rd generation auditions on 11 November 2009, and debuted on 15 January 2010 at SKE48's Team S stage performance."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0392-7317f9c313a2:d01", "start": 140, "end": 188, "text": "On 27 February 2010, she was promoted to Team S."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0392-7317f9c313a2:d01", "start": 189, "end": 236, "text": "Her first SKE48 Senbatsu was for the single \"1!"}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0392-7317f9c313a2:d01", "start": 237, "end": 239, "text": "2!"}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0392-7317f9c313a2:d01", "start": 240, "end": 242, "text": "3!"}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0392-7317f9c313a2:d01", "start": 243, "end": 245, "text": "4!"}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0392-7317f9c313a2:d01", "start": 246, "end": 258, "text": "Yoroshiku!\"."}, "D2S8": {"document_number": 2, "doc_id": "ramdocs-0392-7317f9c313a2:d01", "start": 259, "end": 330, "text": "In the 2011 general elections, Suda placed 36th and entered Undergirls."}, "D2S9": {"document_number": 2, "doc_id": "ramdocs-0392-7317f9c313a2:d01", "start": 331, "end": 378, "text": "In April 2013, she was transferred to Team KII."}, "D2S10": {"document_number": 2, "doc_id": "ramdocs-0392-7317f9c313a2:d01", "start": 379, "end": 436, "text": "She started activities as a Team KII member in July 2013."}, "D2S11": {"document_number": 2, "doc_id": "ramdocs-0392-7317f9c313a2:d01", "start": 437, "end": 504, "text": "In the 2013 general elections, Suda entered senbatsu at 16th place."}, "D2S12": {"document_number": 2, "doc_id": "ramdocs-0392-7317f9c313a2:d01", "start": 505, "end": 572, "text": "In February 2014, during the AKB48 Group Shuffle, it was announced."}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0392-7317f9c313a2:d02", "start": 0, "end": 80, "text": "Akari Yoshida Yoshida passed NMB48's 1st generation auditions in September 2010."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0392-7317f9c313a2:d02", "start": 81, "end": 128, "text": "Her audition song was Tomorrow by Okamoto Mayo."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0392-7317f9c313a2:d02", "start": 129, "end": 162, "text": "Her debut was on October 9, 2010."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0392-7317f9c313a2:d02", "start": 163, "end": 202, "text": "Her stage debut was on January 1, 2011."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0392-7317f9c313a2:d02", "start": 203, "end": 245, "text": "In March 2011, she was selected to Team N."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0392-7317f9c313a2:d02", "start": 246, "end": 312, "text": "Her first NMB48 Senbatsu was the single Zetsumetsu Kurokami Shōjo."}, "D3S7": {"document_number": 3, "doc_id": "ramdocs-0392-7317f9c313a2:d02", "start": 313, "end": 387, "text": "In September 2011, Yoshida was suspended from activities due to a scandal."}, "D3S8": {"document_number": 3, "doc_id": "ramdocs-0392-7317f9c313a2:d02", "start": 388, "end": 428, "text": "Her activities resumed in February 2012."}, "D3S9": {"document_number": 3, "doc_id": "ramdocs-0392-7317f9c313a2:d02", "start": 429, "end": 526, "text": "In the 2013 general elections, Yoshida ranked for the first time, placing 50th with 14,684 votes."}, "D3S10": {"document_number": 3, "doc_id": "ramdocs-0392-7317f9c313a2:d02", "start": 527, "end": 593, "text": "In 2014, her ranked dropped and she placed 72nd with 10,982 votes."}, "D3S11": {"document_number": 3, "doc_id": "ramdocs-0392-7317f9c313a2:d02", "start": 594, "end": 596, "text": "On"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0392-7317f9c313a2:d03", "start": 0, "end": 129, "text": "Akari Hayami Akari Hayami was scouted near her graduation from elementary school and was signed to the agency Stardust Promotion."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0392-7317f9c313a2:d03", "start": 130, "end": 289, "text": "On November 23, 2008, together with Yukina Kashiwa (presently a member of Nogizaka46) and Ayaka Sasaki she was added to her agency's girl group Momoiro Clover."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0392-7317f9c313a2:d03", "start": 290, "end": 405, "text": "The group existed since 2008 and its name signified that they were \"innocent girls who wanted to spread happiness\"."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0392-7317f9c313a2:d03", "start": 406, "end": 593, "text": "At the time, Momoiro Clover performed on the walkways in Yoyogi Park in Shibuya, Tokyo, but with the release of its first indie single in summer of the next year the group quickly rose to"}}, "candidates": [{"candidate_id": "C0", "answer": "8 December 2009", "card_ids": ["ramdocs-0392-7317f9c313a2:d00:c0"]}, {"candidate_id": "C1", "answer": "15 January 2010", "card_ids": ["ramdocs-0392-7317f9c313a2:d01:c0"]}, {"candidate_id": "C2", "answer": "October 9, 2010", "card_ids": ["ramdocs-0392-7317f9c313a2:d02:c0"]}, {"candidate_id": "C3", "answer": "November 23, 2008", "card_ids": ["ramdocs-0392-7317f9c313a2:d03:c0"]}], "original_cards": [{"doc_id": "ramdocs-0392-7317f9c313a2:d00", "card_id": "ramdocs-0392-7317f9c313a2:d00:c0", "entity": "Akari Suda", "scope": "SKE48 debut", "claim": "Akari Suda debuted on 8 December 2009 at SKE48's Team S stage performance.", "answer": "8 December 2009", "quote": "Akari Suda Suda passed SKE48's 3rd generation auditions on 11 November 2009, and debuted on 8 December 2009 at SKE48's Team S stage performance.", "original_document_number": 1}, {"doc_id": "ramdocs-0392-7317f9c313a2:d01", "card_id": "ramdocs-0392-7317f9c313a2:d01:c0", "entity": "Akari Suda", "scope": "SKE48 debut", "claim": "Akari Suda debuted on 15 January 2010 at SKE48's Team S stage performance.", "answer": "15 January 2010", "quote": "Akari Suda passed SKE48's 3rd generation auditions on 11 November 2009, and debuted on 15 January 2010 at SKE48's Team S stage performance.", "original_document_number": 2}, {"doc_id": "ramdocs-0392-7317f9c313a2:d02", "card_id": "ramdocs-0392-7317f9c313a2:d02:c0", "entity": "Akari Yoshida", "scope": "debut", "claim": "Her debut was on October 9, 2010.", "answer": "October 9, 2010", "quote": "Her debut was on October 9, 2010.", "original_document_number": 3}, {"doc_id": "ramdocs-0392-7317f9c313a2:d03", "card_id": "ramdocs-0392-7317f9c313a2:d03:c0", "entity": "Akarin", "scope": "Debut in Momoiro Clover", "claim": "On November 23, 2008, Akari Hayami (Akarin) was added to the agency's girl group Momoiro Clover.", "answer": "November 23, 2008", "quote": "On November 23, 2008, together with Yukina Kashiwa (presently a member of Nogizaka46) and Ayaka Sasaki she was added to her agency's girl group Momoiro Clover.", "original_document_number": 4}], "initial_answers": ["8 December 2009", "15 January 2010", "November 23, 2008"]}

